# -*- coding: utf-8 -*-
"""Greek text for the Rule page. TEXT = {key: translated inner HTML}."""
TEXT = {
"k34706326": "Περί του κανόνος προσευχής",
"kc1ba8633": "Τι λένε οι πηγές της Εκκλησίας για το πόσο πρέπει να προσευχόμαστε, και για την προσευχή κατά την δύναμη του καθενός. Η σελίδα αυτή παραθέτει τις πηγές· δεν προσθέτει συμβουλές σε αυτές.",
"ka7965ff8": "<strong>Διαβάστε πρώτα αυτό.</strong> Καθετί στο Plithos είναι αναφορά, όχι μέτρο για εσάς. Οι προσευχές, ο κανόνας της νηστείας, οι ώρες και οι ακολουθίες παρατίθενται εδώ πλήρεις επειδή είναι η κληρονομιά της Εκκλησίας και πρέπει να είναι προσιτές σε όλους. Το να παρατεθούν πλήρεις δεν σημαίνει ότι οφείλει κανείς να τα τηρεί όλα.",
"kef5c7431": "Τον κανόνα που τηρείτε τον ορίζει ο πνευματικός σας πατέρας, κατά τη γνώση σας, τη δύναμή σας και τις περιστάσεις σας. Τίποτε σε αυτόν τον ιστότοπο δεν υπερισχύει εκείνου, και τίποτε εδώ δεν είναι κρίση για όποιον προσεύχεται λιγότερο από όσα είναι τυπωμένα. Όποιος λέει το Πάτερ ημών τρεις φορές την ημέρα και το εννοεί, τηρεί τον κανόνα που έδωσε η Εκκλησία τον πρώτο αιώνα.",
"kfd250c56": "Η σελίδα αυτή παραθέτει όσα λένε οι πηγές και δεν προσθέτει δική της συμβουλή. Όπου μια πρόταση δεν φέρει παραπομπή, είναι δήλωση για τον ιστότοπο αυτόν, όχι οδηγία για την προσευχή σας. Η καθοδήγηση ανήκει στον ιερέα σας, που γνωρίζει τη ζωή σας· ο ιστότοπος αυτός δεν τη γνωρίζει.",
"kd06d4f8a": "Ποιος ήταν πράγματι ο αρχαιότερος κανόνας",
"kc90dad01": "Το αρχαιότερο σωζόμενο χριστιανικό εγχειρίδιο πράξεως είναι η Διδαχή, περί το έτος 100. Ο κανόνας προσευχής της είναι τρία Πάτερ ημών την ημέρα.",
"kadda83fe": "Τρις της ημέρας ούτω προσεύχεσθε.",
"k513c7122": "Διδαχή 8 &middot; μτφρ. M. B. Riddle, 1886 &middot; <a href=\"/library#work=didache\">διαβάστε το στη Βιβλιοθήκη</a>",
"k355facce": "Το ίδιο κείμενο, δύο κεφάλαια πριν, διατυπώνει την αρχή του μέτρου ευθέως, και δεν πρόκειται για νεωτερική χαλάρωση αλλά για το αρχαιότερο που έγραψε η Εκκλησία επί του θέματος:",
"k0133b448": "Ει μεν γαρ δύνασαι βαστάσαι όλον τον ζυγόν του Κυρίου, τέλειος έση· ει δ' ου δύνασαι, ο δύνη, τούτο ποίει.",
"kec4ccf0b": "Διδαχή 6 &middot; μτφρ. M. B. Riddle, 1886 &middot; <a href=\"/library#work=didache\">διαβάστε το στη Βιβλιοθήκη</a>",
"ka800cdac": "Οι πληρέστερες ακολουθίες προσευχής των μεταγενέστερων προσευχηταρίων αναπτύχθηκαν έπειτα από αυτό. Η Διδαχή είναι απλώς ο αρχαιότερος γραπτός κανόνας που έχει η Εκκλησία, και αυτό είναι που ζητεί.",
"kc8529ac1": "Το πλήθος δεν είναι το μέτρο",
"k605c07f5": "Ο άγιος Ιωάννης ο Κασσιανός, καταγράφοντας τη διδασκαλία των Αιγυπτίων πατέρων στις αρχές του πέμπτου αιώνα, προειδοποιεί κατά του να λογαριάζει κανείς την προσευχή με τις ώρες που ορίζει τυπικά γι' αυτήν:",
"kda219ca8": "Διότι ελάχιστα προσεύχεται εκείνος που συνήθισε να προσεύχεται μόνο τις ώρες που κλίνει τα γόνατα.",
"k87ef1fff": "Άγιος Ιωάννης Κασσιανός, Συνομιλίαι 10.14 &middot; μτφρ. Edgar C. S. Gibson &middot; <a href=\"/library#work=cassian-conferences\">διαβάστε το στη Βιβλιοθήκη</a>",
"k6f06dcb5": "Το μέτρο της προσευχής κατά τον Κασσιανό είναι λοιπόν ευρύτερο από τις ορισμένες ώρες, και η πρόταση απευθύνεται σε όσους την περιορίζουν σε αυτές. Δεν εισάγει ο ίδιος την ιδέα. Ο Απόστολος είχε ήδη δώσει τον κανόνα σε μορφή που κανένα ρολόι δεν χωρεί:",
"k9d16dd79": "Διά πάσης προσευχής και δεήσεως προσευχόμενοι εν παντί καιρώ εν Πνεύματι, και εις αυτό τούτο αγρυπνούντες εν πάση προσκαρτερήσει και δεήσει περί πάντων των αγίων·",
"kd45e4afe": "Προς Εφεσίους 6:18",
"k8ff6957a": "Και ακόμη συντομότερα: <em>αδιαλείπτως προσεύχεσθε</em> (Α΄ Θεσσαλονικείς 5:17). Ο κανόνας των ωρισμένων ωρών υπηρετεί αυτό· δεν το εξαντλεί.",
"k94022491": "Μια σειρά, όχι κλίμακα",
"k6f5ac9c2": "Όσα ακολουθούν δεν είναι βαθμίδες που ορίζει το Plithos. Είναι μια σειρά όσων περιέχουν οι πηγές και τα παραδεδομένα βιβλία, κατά το πόσο ζητεί καθένα από την ημέρα. <strong>Ποιο από αυτά αρμόζει στον καθένα είναι ερώτημα για τον πνευματικό του πατέρα, όχι για τη σελίδα αυτή.</strong>",
"kbd0070ec": "Δεν είναι κλίμακα, και το πρώτο σημείο είναι ο λόγος για τον οποίο δεν είναι. Η ευχή του Ιησού στέκει πρώτη επειδή ζητεί τα λιγότερα από τις περιστάσεις του ανθρώπου, όχι επειδή ζητεί τα λιγότερα από τον άνθρωπο. Η ίδια ευχή είναι εκείνη που οι ησυχαστές πατέρες περιγράφουν ως το όλον της προσευχής, και εκείνη που δίδεται στους προχωρημένους αντί για καθετί γραπτό. Στέκει και στα δύο άκρα συγχρόνως.",
"kec53651e": "Η ευχή του Ιησού",
"kd76e85df": "Όταν δεν υπάρχει χρόνος, ούτε βιβλίο, ούτε ησυχία - στο ταξίδι, στην εργασία, στην ασθένεια, όταν δεν μπορεί κανείς να σταθεί ή να μιλήσει",
"k15c8fcc6": "Η ευχή του Ιησού στην πλήρη μορφή της: <em>Κύριε Ιησού Χριστέ, Υιέ του Θεού, ελέησόν με τον αμαρτωλόν.</em> Όπου και αυτό είναι πολύ, οι Πατέρες επιτρέπουν συντομότερες μορφές - <em>Κύριε Ιησού Χριστέ, ελέησόν με</em>, ή απλώς <em>Κύριε, ελέησον</em>. Δεν χρειάζεται βιβλίο, ούτε ορθοστασία, ούτε φωνή, και μπορεί να συνοδεύει μια συνηθισμένη εργάσιμη ημέρα.",
"k433c6e1a": "<a href=\"/prayers#s=heart\">Η ευχή του Ιησού, και η συμβουλή των Πατέρων για την τήρησή της</a>",
"k0607d349": "Έρχεται πρώτη επειδή επιβιώνει σε κάθε περίσταση, όχι επειδή είναι το ελάχιστο από όσα υπάρχουν εδώ. Κασσιανός, Συνομιλίαι 10.14: \"ελάχιστα προσεύχεται εκείνος που συνήθισε να προσεύχεται μόνο τις ώρες που κλίνει τα γόνατα.\"",
"k4fbd7571": "Το Πάτερ ημών, τρεις φορές την ημέρα",
"kccf34183": "Ορισμένος κανόνας σε ορισμένες ώρες, όταν αυτό είναι δυνατόν",
"k6c98a369": "Ο κανόνας του αρχαιότερου χριστιανικού εγχειριδίου που έχουμε. Είναι μικρός κανόνας, αλλά είναι κανόνας σε ορισμένες ώρες, και έτσι ζητεί περισσότερα από μια διακεκομμένη ημέρα απ' όσα ζητεί η ευχή του Ιησού.",
"kb80095bf": "Διδαχή 8.",
"k73f947ac": "Ο κανόνας του αγίου Σεραφείμ του Σάρωφ",
"kbeb11458": "Για όσους η εργασία τους δεν αφήνει περιθώριο για μεγαλύτερο κανόνα",
"kba90cd4c": "Με το σήκωμα, στεκόμενος μπροστά στις εικόνες: το Πάτερ ημών τρεις φορές, το <em>Θεοτόκε Παρθένε, χαίρε</em> τρεις φορές, και το Σύμβολο της Πίστεως μία φορά. Έπειτα στην εργασία, λέγοντας ήσυχα την ευχή του Ιησού όλο το πρωί, και το <em>Υπεραγία Θεοτόκε, σώσόν με</em> το απόγευμα. Ο ίδιος σύντομος κανόνας πάλι πριν από τον ύπνο.",
"k6464f90a": "Ο άγιος Σεραφείμ τον έδωσε σε εργάτες και οικογενειάρχες που δεν μπορούσαν να τηρήσουν τις πληρέστερες πρωινές και βραδινές προσευχές, και δεν τον αντιμετώπισε ως υποχώρηση που πρέπει να ξεπεραστεί. Είναι κανόνας ωρισμένων προσευχών σε ωρισμένες ώρες, ενωμένος με προσευχή που διατρέχει την εργάσιμη ημέρα, γι' αυτό και στέκει εδώ και όχι χαμηλότερα.",
"kc823332f": "Άγιος Σεραφείμ του Σάρωφ, στις οδηγίες του προς λαϊκούς. Οι ίδιες οι προσευχές βρίσκονται στη σελίδα των Προσευχών.",
"k3041ac63": "Πρωί και βράδυ",
"k225e3ccd": "Ο συνήθης κανόνας του προσευχηταρίου για τον λαϊκό",
"kf4d2a2e5": "Οι πρωινές προσευχές με το σήκωμα και οι βραδινές πριν από τον ύπνο, λεγόμενες με προσοχή και όχι βιαστικά.",
"k98ad4446": "<a href=\"/prayers#s=daily\">Πρωινές και βραδινές προσευχές</a>",
"k8ad36869": "Ο άγιος Θεοφάνης ο Έγκλειστος θεωρούσε τις πρωινές και βραδινές προσευχές του προσευχηταρίου απολύτως επαρκείς για λαϊκό που ξεκινά. Δείτε τη σημείωση στη σελίδα των Προσευχών για την πληρέστερη συμβουλή.",
"k4cecadd4": "Με τις Ώρες",
"kefb7d0a1": "Όπου το επιτρέπει η ημέρα",
"k8fb45542": "Οι σύντομες ακολουθίες μέσα στην ημέρα, από την Α΄ Ώρα ως το Απόδειπνο.",
"k6b300612": "<a href=\"/prayers#s=hours\">Οι Ώρες</a>",
"k61610f0a": "Οι τρεις καθημερινές προσευχές της Διδαχής είναι ο σπόρος αυτού του κύκλου. Οι πλήρεις Ώρες δίδονται στο Ωρολόγιον.",
"kb3c5ab3d": "Προετοιμασία για τη θεία Κοινωνία",
"k8dbdf873": "Πριν από τη μετάληψη των Μυστηρίων",
"kced3fbfd": "Η Ακολουθία της Θείας Μεταλήψεως, οι δύο ευχές που λέγονται στο ποτήριο, και η ευχαριστία μετά. Πόσο από την Ακολουθία λέγεται, και αν τηρείται το προηγούμενο βράδυ ή το πρωί, διαφέρει κατά την παράδοση και ορίζεται από τον πνευματικό πατέρα. Δείτε παρακάτω τι θέτουν οι Πατέρες ως την πραγματική προϋπόθεση της προσελεύσεως.",
"k8f37e928": "<a href=\"/prayers#s=communion\">Οι ευχές της θείας Κοινωνίας, στις τρεις φάσεις τους</a>",
"k88dda4ec": "Η πράξη διαφέρει αισθητά μεταξύ της σλαβικής και της ελληνικής παραδόσεως, τόσο στην αναμενόμενη προετοιμασία όσο και στη συχνότητα με την οποία κοινωνούν οι πιστοί.",
"ka6cba0b8": "Όταν δεν μπορείτε να τηρήσετε τον κανόνα σας",
"k87db3602": "Το ταξίδι, η ασθένεια, η νυχτερινή εργασία, τα μικρά παιδιά, το πένθος και η εξάντληση διακόπτουν όλα έναν κανόνα. Δύο πράγματα από τα παραπάνω κείμενα αφορούν άμεσα αυτό.",
"k8dcf4ab6": "<strong>Η Διδαχή δεν παρουσιάζει τον κανόνα ως όλα ή τίποτε.</strong> Η οδηγία της δεν είναι να τηρήσεις ολόκληρο τον ζυγό ειδάλλως τίποτε, αλλά ότι όπου δεν μπορεί να βασταχθεί το όλον, \"ο δύνη, τούτο ποίει\".",
"ka4ac033d": "<strong>Η προσευχή δεν περιορίζεται στις ώρες της ορθοστασίας.</strong> Αυτή είναι η δύναμη της παραπάνω προτάσεως του Κασσιανού: ελέγχει όσους λογαριάζουν την προσευχή τους μόνο με τις ώρες που κλίνουν το γόνυ, πράγμα που τοποθετεί την προσευχή εκτός εκείνων των ωρών μέσα στον λογαριασμό και όχι έξω από αυτόν. Η ευχή του Ιησού στις συντομότερες παραδεδομένες μορφές της δεν απαιτεί ούτε βιβλίο, ούτε στάση, ούτε φωνή.",
"k1c9eeaa9": "Τι θέτουν οι Πατέρες ως προϋπόθεση της προσελεύσεως",
"keac4f2df": "Η Ακολουθία της Θείας Μεταλήψεως είναι πραγματικό αγαθό και πραγματική κληρονομιά. Δεν είναι αυτό που καθιστά κάποιον ικανό να μεταλάβει. Επ' αυτού οι Πατέρες είναι ρητοί, και έγραφαν πολύ πριν υπάρξει οποιαδήποτε τυπωμένη ακολουθία προετοιμασίας.",
"kc356b366": "Ο άγιος Ιωάννης ο Χρυσόστομος, κηρύττοντας στην προς Εβραίους, θέτει ακριβώς το ερώτημα του πόσο συχνά και πόσο πολύ, και αρνείται να το απαντήσει με αυτούς τους όρους:",
"kce69ff57": "Τι λοιπόν; Ποιους θα επαινέσουμε; Εκείνους που μεταλαμβάνουν μία φορά τον χρόνο; Εκείνους που μεταλαμβάνουν πολλές φορές; Εκείνους που μεταλαμβάνουν λίγες φορές; Ούτε εκείνους που μεταλαμβάνουν μία φορά, ούτε εκείνους που μεταλαμβάνουν συχνά, ούτε εκείνους που μεταλαμβάνουν σπάνια, αλλά εκείνους που προσέρχονται με καθαρή συνείδηση, από καθαρή καρδιά, με ανεπίληπτη ζωή. Οι τέτοιοι ας προσέρχονται διαρκώς· εκείνοι όμως που δεν είναι τέτοιοι, ούτε μία φορά.",
"k2d880e69": "Άγιος Ιωάννης Χρυσόστομος, Ομιλία 17 εις την προς Εβραίους &middot; μτφρ. Frederic Gardiner &middot; <a href=\"/library#work=chrysostom-homilies-hebrews\">διαβάστε το στη Βιβλιοθήκη</a>",
"k3448180a": "Το κριτήριο που ονομάζει ο Χρυσόστομος είναι η κατάσταση της συνειδήσεως. Δεν ονομάζει αριθμό, ούτε κοινωνιών ούτε προσευχών που λέγονται προηγουμένως, και παραμερίζει το ερώτημα της συχνότητας ως λανθασμένο ερώτημα.",
"k4bc3e896": "Ο άγιος Ιωάννης ο Κασσιανός πραγματεύεται το άλλο ήμισυ, και ο τίτλος του κεφαλαίου το λέει καθαρά: <em>ότι αν και ομολογούμε πως δεν μπορούμε να είμαστε χωρίς αμαρτία, εντούτοις δεν οφείλουμε να απέχουμε από την Κοινωνία του Κυρίου.</em>",
"k3620ced2": "Δεν οφείλουμε όμως να απέχουμε από την Κοινωνία του Κυρίου επειδή ομολογούμε τους εαυτούς μας αμαρτωλούς, αλλά να σπεύδουμε προς αυτήν ολοένα προθυμότερα για την ίαση της ψυχής μας και τον καθαρμό του πνεύματός μας, και να ζητούμε μάλλον φάρμακο για τα τραύματά μας με ταπείνωση φρονήματος και πίστη, θεωρώντας τους εαυτούς μας αναξίους να λάβουν τόσο μεγάλη χάρη.",
"k99dd8e07": "Αλλιώς δεν μπορούμε να λάβουμε επαξίως την Κοινωνία ούτε μία φορά τον χρόνο, όπως κάνουν κάποιοι που ζουν σε μοναστήρια και θεωρούν την αξία και την αγιότητα και το τίμημα των επουρανίων μυστηρίων τέτοια, ώστε να νομίζουν πως κανείς εκτός από αγίους και αμώμους δεν πρέπει να τολμά να τα λάβει, και όχι μάλλον ότι εκείνα θα μας κάνουν αγίους και καθαρούς με το να τα λάβουμε. Και έτσι πέφτουν σε μεγαλύτερη οίηση και αλαζονεία από εκείνη που τους φαίνεται ότι αποφεύγουν, επειδή τη στιγμή που τα λαμβάνουν θεωρούν ότι είναι άξιοι να τα λάβουν.",
"kb8b440b1": "Άγιος Ιωάννης Κασσιανός, Συνομιλίαι 23.21 &middot; μτφρ. Edgar C. S. Gibson &middot; <a href=\"/library#work=cassian-conferences\">διαβάστε το στη Βιβλιοθήκη</a>",
"kcab416e7": "Το επιχείρημα του Κασσιανού είναι ότι η αποχή από αίσθημα αναξιότητας είναι η ίδια η μεγαλύτερη οίηση, αφού εκείνος που απέχει ώσπου να γίνει άξιος υποθέτει ότι κάποια άλλη ημέρα θα ήταν. Απέναντι σε αυτό θέτει εκείνο για το οποίο λέει ότι υπάρχουν τα Μυστήρια: όχι αμοιβή για τους ήδη καθαρούς, αλλά το μέσον με το οποίο, κατά τα λόγια του, θα μας κάνουν αγίους και καθαρούς με το να τα λάβουμε.",
"k1ceaa3c4": "Τι βάζει η Εκκλησία στο στόμα εκείνου που κοινωνεί",
"k15496498": "Αυτό δεν είναι χαμήλωμα του μέτρου. Είναι το μέτρο, και η Εκκλησία το βάζει στο στόμα καθενός που προσέρχεται. Η ομολογία που λέγεται στο ποτήριο, φωναχτά, από όλο το εκκλησίασμα, δεν λέει ότι εκείνος που τη λέει έχει φθάσει:",
"kffb87ae9": "Πιστεύω, Κύριε, και ομολογώ ότι συ ει αληθώς ο Χριστός, ο Υιός του Θεού του ζώντος, ο ελθών εις τον κόσμον αμαρτωλούς σώσαι, ων πρώτος ειμί εγώ.",
"kd40a122c": "Η ευχή προ της Μεταλήψεως &middot; κατά το Α΄ Τιμόθεον 1:15 &middot; <a href=\"/prayers#s=communion\">διαβάστε την στο προσευχητάριο</a>",
"k91d95d94": "Τα ίδια τα λόγια του Αποστόλου είναι <em>Χριστός Ιησούς ήλθεν εις τον κόσμον αμαρτωλούς σώσαι, ων πρώτος ειμί εγώ</em>, και η Εκκλησία δεν τα άφησε στην επιστολή. Τα έθεσε στο ποτήριο και τα έδωσε σε κάθε κοινωνούντα να τα λέει σε πρώτο πρόσωπο, την ημέρα που μεταλαμβάνει. Άγιοι είναι εκείνοι που είπαν αυτή την πρόταση και την εννοούσαν, όχι εκείνοι που έφθασαν σε σημείο όπου έπαυσε να ισχύει. Η χάρη δίδεται· εκείνο που ζητείται από εμάς είναι να αποκριθούμε, να τηρήσουμε τις εντολές που μας δόθηκαν, και να εξακολουθούμε να αποκρινόμαστε αφού αποτύχουμε να τις τηρήσουμε.",
"kf78cb40a": "Τι σημαίνει αυτό στην πράξη",
"k87e5b047": "<strong>Η Ακολουθία δεν είναι μεταξύ των κανονικών προϋποθέσεων.</strong> Κανένας κανόνας της Εκκλησίας δεν την απαιτεί πριν από τη μετάληψη, και η ορισμένη τυπωμένη σειρά είναι μεταγενέστερη των κανόνων· πόσο από αυτήν λέγεται το ορίζει ο πνευματικός πατέρας.",
"k0e542bbd": "<strong>Εκείνο που ονομάζει η παράδοση</strong> πριν από το ποτήριο είναι συνείδηση που δεν αναπαύεται σε αμετανόητη αμαρτία, ειρήνη με τον πλησίον, η ευχαριστιακή νηστεία, και υπακοή στον πνευματικό πατέρα ως προς την εξομολόγηση. Ο Κασσιανός πραγματεύεται ευθέως την περίπτωση εκείνου που απέσχε από αίσθημα αναξιότητας, στο παραπάνω χωρίο· ο Χρυσόστομος πραγματεύεται εκείνον που λογαριάζει με αριθμούς.",
"k21c606eb": "<strong>Η ευχαριστιακή νηστεία είναι κανονική, όχι εθιμική.</strong> Ο Αφρικανικός Κώδικας την απαιτούσε, επιτρέποντας μία εξαίρεση τον χρόνο, την ημέρα που μνημονεύεται το Δείπνο του Κυρίου:",
"k253a3d17": "Ότι τα Μυστήρια του θυσιαστηρίου δεν πρέπει να τελούνται παρά μόνο από νηστικούς, εκτός από τη μία επέτειο του εορτασμού του Δείπνου του Κυρίου· διότι αν η μνήμη κάποιων κεκοιμημένων, επισκόπων ή άλλων, πρόκειται να γίνει το απόγευμα, ας γίνει μόνο με προσευχές, εφόσον οι λειτουργούντες έχουν ήδη γευματίσει.",
"kb289f398": "Αφρικανικός Κώδικας (419), Κανών 41 &middot; μτφρ. Henry R. Percival, 1900 &middot; <a href=\"/library#work=canons-ecumenical\">διαβάστε τον στη Βιβλιοθήκη</a>",
"kfd9e4371": "Η εν Τρούλλω Σύνοδος έλαβε τον κανόνα αυτόν και αφαίρεσε την εξαίρεση:",
"k97125890": "Κανών της Συνόδου της Καρχηδόνος λέει ότι τα άγια μυστήρια του θυσιαστηρίου δεν πρέπει να τελούνται παρά μόνο από νηστικούς, εκτός από μία ημέρα τον χρόνο κατά την οποία εορτάζεται το Δείπνο του Κυρίου. Τότε, ίσως εξαιτίας ορισμένων περιστάσεων χρησίμων στην Εκκλησία στους τόπους εκείνους, και αυτοί οι άγιοι Πατέρες έκαναν χρήση της οικονομίας αυτής. Επειδή όμως τίποτε δεν μας οδηγεί να εγκαταλείψουμε την ακρίβεια, ορίζουμε να ακολουθείται η αποστολική και πατερική παράδοση· και καθορίζουμε ότι δεν είναι ορθό να καταλύεται η νηστεία την πέμπτη ημέρα της τελευταίας εβδομάδος της Τεσσαρακοστής, και να ατιμάζεται έτσι ολόκληρη η Τεσσαρακοστή.",
"k5c17110d": "Η εν Τρούλλω, η Πενθέκτη Σύνοδος (692), Κανών 29 &middot; μτφρ. Henry R. Percival, 1900 &middot; <a href=\"/library#work=canons-ecumenical\">διαβάστε τον στη Βιβλιοθήκη</a>",
"k4b650236": "Εκείνο που απαιτούν οι κανόνες είναι η νηστεία. Ο υπολογισμός της από τα προηγούμενα μεσάνυχτα είναι το έθιμο που τη φέρει, και είναι η συνήθης πράξη σε κάθε δικαιοδοσία. Όπου η Λειτουργία τελείται το εσπέρας, όπως η Προηγιασμένη και όπως μπορούν να τελεσθούν οι Λειτουργίες των Χριστουγέννων, των Θεοφανείων, της Μεγάλης Πέμπτης και του Μεγάλου Σαββάτου, το διάστημα το ορίζει ο επίσκοπος αντί να μετράται από τα μεσάνυχτα. Το φάρμακο που πρέπει να ληφθεί, η ασθένεια, η εγκυμοσύνη, η βρεφική και η βαθιά ηλικία αντιμετωπίζονται από τον πνευματικό πατέρα. Το να ρωτήσει κανείς δεν είναι το ίδιο με το να απαλλαγεί, και κανένα από τα δύο δεν είναι λόγος να μένει μακριά από το ποτήριο.",
"kc182b483": "<strong>Οι δύο ευχές που λέγονται στο ποτήριο</strong> - το \"Πιστεύω, Κύριε, και ομολογώ\" και το \"Του Δείπνου σου του μυστικού\" - λέγονται φωναχτά με όλο το εκκλησίασμα στις περισσότερες ενορίες.",
"kaebd6892": "Οι κανόνες είναι μοναστικοί στη μορφή· η ζωή που ζητούν δεν είναι",
"keedea2a4": "Σχεδόν κάθε ορισμένος κανόνας τυπωμένος σε προσευχητάριο πήρε τη σημερινή του μορφή σε μοναστήρι, και γι' αυτό η προετοιμασία μπορεί να διαβάζεται σαν να απευθύνεται σε κάποιον άλλον. Η αντίρρηση είναι τόσο παλιά ώστε ο άγιος Ιωάννης ο Χρυσόστομος τη βάζει στο στόμα των ακροατών του πριν την απαντήσει:",
"k3f765fe1": "Δεν είμαι, θα πεις, από τους μοναχούς, αλλά έχω και γυναίκα και παιδιά και τη φροντίδα του σπιτιού. Αυτό ακριβώς είναι που τα κατέστρεψε όλα, το ότι νομίζεις πως η ανάγνωση των θείων Γραφών ανήκει μόνο σε εκείνους, ενώ εσύ τη χρειάζεσαι πολύ περισσότερο από αυτούς. Διότι όσοι κατοικούν μέσα στον κόσμο και δέχονται κάθε ημέρα τραύματα, αυτοί έχουν τη μεγαλύτερη ανάγκη από φάρμακα.",
"kebad4fa3": "Άγιος Ιωάννης Χρυσόστομος, Ομιλία 2 εις τον Ματθαίον &middot; μτφρ. George Prevost &middot; <a href=\"/library#work=chrysostom-homilies-matthew\">διαβάστε το στη Βιβλιοθήκη</a>",
"k5eee983b": "Το ίδιο λέει και για τον ίδιο τον τρόπο ζωής, και το λέει ως άρνηση να νομοθετήσει την έρημο:",
"k00cd498f": "Δεν θέτω νόμο να καταλάβετε τα όρη και τις ερήμους, αλλά να είστε αγαθοί και συνετοί και σώφρονες, κατοικώντας μέσα στην πόλη.",
"kc7ddce00": "Άγιος Ιωάννης Χρυσόστομος, Ομιλία 7 εις τον Ματθαίον &middot; μτφρ. George Prevost &middot; <a href=\"/library#work=chrysostom-homilies-matthew\">διαβάστε το στη Βιβλιοθήκη</a>",
"k99a23dda": "Και στην προς Ρωμαίους αντιμετωπίζει την ιδέα ότι η συνηθισμένη ζωή είναι λάθος αποδέκτης των εντολών ως κατηγορία εναντίον της πίστεως και όχι ως περιγραφή της:",
"k91017238": "Διότι αν δεν υπάρχει δυνατότητα να είναι μαθητής εκείνος που ζει μέσα στις πόλεις, τούτο είναι βαριά κατηγορία εναντίον αυτού του τρόπου ζωής, ότι δηλαδή πρέπει να αφήσουμε τις πόλεις και να τρέξουμε στις ερήμους. Δείξε μου όμως άνθρωπο που έχει γυναίκα και παιδιά και οικογένεια, και όμως επιδιώκει τη σοφία. Τι λοιπόν να πούμε για όλα αυτά; Δεν πρέπει να σκύψουμε το κεφάλι και να ντραπούμε; Διότι ο Χριστός δεν μας έδωσε τέτοια εντολή· αλλά ποια; Ας λάμψει το φως σας έμπροσθεν των ανθρώπων, όχι όρη και έρημοι και ερημότοποι και απόμερα μέρη.",
"kafb2fb07": "Άγιος Ιωάννης Χρυσόστομος, Ομιλία 26 εις την προς Ρωμαίους &middot; μτφρ. J. B. Morris και W. H. Simcox &middot; <a href=\"/library#work=chrysostom-homilies-romans\">διαβάστε το στη Βιβλιοθήκη</a>",
"ke1ee6e3e": "Προσέχει, στην πρόταση που ακολουθεί, να μη διαβαστεί ως υποτίμηση των μοναχών: λέει ότι μιλά \"όχι κακίζοντας εκείνους που ανέλαβαν τα όρη, αλλά θρηνώντας εκείνους που κατοικούν στις πόλεις, επειδή εξόρισαν από εκεί την αρετή.\" Ο μοναχός παραδίδει το ίδιο του το θέλημα σε γέροντα. Στον λαϊκό δίδεται το ίδιο πράγμα να παραδώσει, σε έναν γάμο, σε εργασία που δεν διάλεξε, στην υπομονή που κοστίζει ένα σπιτικό, και του ζητείται σε μορφή που κανένας κανόνας δεν μπορεί να τυπώσει εκ των προτέρων.",
"ka438020e": "Νηστεία, εξομολόγηση, και τα υπόλοιπα της προετοιμασίας",
"k67ac3841": "Η προετοιμασία δεν είναι μόνο προσευχή. Η νηστεία της Τετάρτης και της Παρασκευής είναι το αρχαιότερο μέρος της, και βρίσκεται στο ίδιο κεφάλαιο της Διδαχής που δίνει τον κανόνα της προσευχής:",
"ke069eea2": "Οι δε νηστείαι υμών μη έστωσαν μετά των υποκριτών· νηστεύουσι γαρ δευτέρα σαββάτων και πέμπτη· υμείς δε νηστεύσατε τετράδα και παρασκευήν. Μηδέ προσεύχεσθε ως οι υποκριταί, αλλ' ως εκέλευσεν ο Κύριος εν τω Ευαγγελίω αυτού, ούτω προσεύχεσθε· Πάτερ ημών ο εν τω ουρανώ...",
"k4e4ee152": "Η προειδοποίηση στο χωρίο αφορά και τα δύο μέρη: όχι το να μη νηστεύει κανείς αλλά το να νηστεύει <em>ως οι υποκριταί</em>, και όχι το να μην προσεύχεται αλλά το να προσεύχεται <em>ως οι υποκριταί</em>. Η Διδαχή δίνει τους δύο κανόνες με μια ανάσα και προσδιορίζει καθέναν με τον ίδιο τρόπο.",
"k901f0415": "Η εξομολόγηση πριν από τη θεία Κοινωνία αναμένεται σε ορισμένες παραδόσεις και σε άλλες όχι, και η διαφορά είναι μακραίωνη και όχι ζήτημα χαλαρότητας. Αξίζει να εκτεθεί, επειδή όποιος έμαθε να προετοιμάζεται στη μία παράδοση και βρεθεί έπειτα σε ενορία της άλλης μπορεί εύκολα να εκλάβει μια διαφορά εθίμου ως κρίση εναντίον του.",
"k34d94fda": "<strong>Στις σλαβικές Εκκλησίες</strong> - τη Ρωσική, τη Ρωσική Διασποράς, την OCA, την Ουκρανική, τη Σερβική - η εξομολόγηση αναμένεται συνήθως πριν από κάθε θεία Κοινωνία. Η προετοιμασία περιλαμβάνει κατά συνήθεια τους τρεις κανόνες, στον Σωτήρα, στη Θεοτόκο και στον Φύλακα Άγγελο, και συχνά τον Ακάθιστο στον Γλυκύτατο Ιησού, επιπλέον των ευχών της προετοιμασίας· και η παρουσία στην αγρυπνία ή τον εσπερινό του προηγουμένου βραδιού αναμένεται ως μέρος της προετοιμασίας και όχι ως χωριστή ευλάβεια.",
"k3c46f09c": "<strong>Στην ελληνική, την αντιοχειανή και τη ρουμανική πράξη</strong> η εξομολόγηση χωρίζεται συχνότερα από τη θεία Κοινωνία και τηρείται σε διαστήματα που ορίζει ο πνευματικός πατέρας, συχνά στις τέσσερις νηστείες. Η προετοιμασία σημαίνει συχνότερα τις ευχές της προετοιμασίας παρά το πλήρες σύνολο των κανόνων και του ακαθίστου, και η εσπερινή ακολουθία συνιστάται θερμά χωρίς να γίνεται προϋπόθεση της μεταλήψεως.",
"kbf226744": "Και τα δύο είναι η παγιωμένη πράξη ολόκληρων τοπικών Εκκλησιών, και καθένα τηρείται υπό την καθοδήγηση του κλήρου της Εκκλησίας εκείνης. Ο κανόνας του καθενός εδώ προέρχεται από τον δικό του πνευματικό πατέρα, όχι από όποια περιγραφή τύχει να διαβάσει πρώτη.",
"k7edee590": "Ένας τελευταίος λόγος για το μέτρο",
"k95bf9581": "Ο κανόνας υπάρχει ώστε ούτε να ενδίδουμε στη ραθυμία από τη μια, ούτε να πιέζουμε τους εαυτούς μας πέρα από τη δύναμή μας από την άλλη. Ο άγιος Θεοφάνης ο Έγκλειστος δίδασκε ότι ο δρόμος έχει δύο χαντάκια: δεξιά, ζήλος χωρίς γνώση· αριστερά, ραθυμία. Η υπερβολή φέρνει τον αρχάριο στην εξάντληση και την απόγνωση όταν αποτυγχάνει, και στην υπερηφάνεια όταν επιτυγχάνει. Ο άγιος Ιγνάτιος Μπριαντσανίνωφ έγραψε ότι ο κανόνας υπάρχει για εσένα· εσύ δεν υπάρχεις για τον κανόνα, αλλά ζεις για τον Κύριο, και οφείλεις να κρατάς την ελευθερία της διακρίσεως.",
"kd192a6bd": "Άρχισε από λίγα. Είναι καλύτερο να πεις λίγες προσευχές με προσοχή παρά να τρέξεις βιαστικά πολλές. Αν έχεις πνευματικό πατέρα, κράτα τον κανόνα που σου δίνει και μην αλλάξεις τίποτε χωρίς την ευλογία του· αν δεν έχεις ακόμη, κράτα μέτριο κανόνα κατά τη δύναμή σου και ζήτησε τέτοιον πατέρα. Κανένα βιβλίο και καμία σελίδα δεν μπορεί να πάρει τη θέση ζωντανού πατρός εν Χριστώ.",
"kb6eb659b": "Αντλείται από τον άγιο Θεοφάνη τον Έγκλειστο, Περί κανόνος προσευχής, και τον άγιο Ιγνάτιο (Μπριαντσανίνωφ) περί του κανόνος προσευχής &middot; <a href=\"/#guide\">και στον Οδηγό</a>",
"keda0cc2f": "Τίποτε σε αυτόν τον ιστότοπο δεν είναι ζυγαριά στην οποία ζυγίζεται κανείς. Είναι βιβλιοθήκη και ημερολόγιο.",
"kc89cd31d": "Κανόνας προσευχής είναι ένα ορισμένο μέτρο προσευχής που τηρείται σε ορισμένες ώρες. Η σελίδα αυτή εκθέτει τι λένε οι πηγές της Εκκλησίας για το πόσο, και τις μορφές που παίρνει συνήθως ένας κανόνας.",
"k36c2948e": "<strong>Διαβάστε πρώτα τούτο.</strong> Τον κανόνα που τηρείτε τον ορίζει ο πνευματικός σας πατέρας, κατά τη δύναμή σας και τις περιστάσεις σας. Ό,τι είναι τυπωμένο εδώ είναι η κληρονομιά, όχι μέτρο με το οποίο κρίνεται κανείς. Όποιος λέει το Πάτερ ημών τρεις φορές την ημέρα και το εννοεί, τηρεί τον κανόνα που έδωσε η Εκκλησία τον πρώτο αιώνα.",
"k530f73b4": "Από πού προέρχεται ο κανόνας",
"kc776efc1": "Δύο κεφάλαια νωρίτερα το ίδιο κείμενο ορίζει το μέτρο, και είναι το αρχαιότερο που έγραψε η Εκκλησία επί του θέματος:",
"k81f4ff1a": "Όλα όσα βρίσκονται στα προσευχητάρια ήρθαν αργότερα. Και ο κανόνας των ορισμένων ωρών υπηρετεί την προσευχή χωρίς να την εξαντλεί: το <em>αδιαλείπτως προσεύχεσθε</em> του Αποστόλου (Α΄ Θεσσαλονικείς 5:17) είναι το ευρύτερο μέτρο, και ο άγιος Ιωάννης ο Κασσιανός, καταγράφοντας τους Αιγυπτίους πατέρες, το λέει κοφτά.",
"k071c623f": "Οι μορφές που παίρνει ένας κανόνας",
"k28364d47": "Αυτές είναι οι μορφές που παίρνει συνήθως ο κανόνας ενός λαϊκού, κατά το πόσο απαιτεί από την ημέρα. Δεν είναι σκάλα προς ανάβαση: η πρώτη είναι εκείνο που οι ησυχαστές πατέρες περιγράφουν ως το σύνολο της προσευχής, και εκείνο που δίνεται στους προχωρημένους αντί για όλα τα γραπτά. <strong>Ποια από αυτές ταιριάζει σε εσάς είναι ζήτημα του πνευματικού σας πατέρα.</strong>",
"kf8b6b4bc": "Προσευχή χωρίς ορισμένες ώρες &middot; όταν δεν υπάρχει χρόνος, ούτε βιβλίο, ούτε ησυχία",
"k491be6c4": "<em>Κύριε Ιησού Χριστέ, Υιέ του Θεού, ελέησόν με τον αμαρτωλόν.</em> Όπου και τούτο είναι πολύ, οι Πατέρες επιτρέπουν συντομότερες μορφές - <em>Κύριε Ιησού Χριστέ, ελέησόν με</em>, ή απλώς <em>Κύριε, ελέησον</em>. Δεν χρειάζεται βιβλίο, ούτε ορθοστασία, ούτε φωνή, και μπορεί να συνοδεύει μια ημέρα εργασίας. Έρχεται πρώτη επειδή αντέχει σε κάθε περίσταση, όχι επειδή είναι η ελάχιστη από όσα υπάρχουν εδώ.",
"k2d14e1b1": "Σύντομος κανόνας σε ορισμένες ώρες &middot; η Διδαχή",
"k25c1035a": "Ορισμένες προσευχές μαζί με προσευχή σε όλη την ημέρα &middot; για όσους η εργασία τους δεν αφήνει περιθώριο για περισσότερα",
"ke0ae2493": "Ο άγιος Σεραφείμ τον έδωσε σε εργάτες και οικογενειάρχες που δεν μπορούσαν να τηρήσουν τις πληρέστερες προσευχές, και δεν τον θεώρησε παραχώρηση που θα την ξεπερνούσε κανείς.",
"kc0703990": "Οι πρωινές προσευχές κατά την έγερση και οι βραδινές πριν τον ύπνο, λεγόμενες με προσοχή και όχι βιαστικά. Ο άγιος Θεοφάνης ο Έγκλειστος θεωρούσε ότι αυτές αρκούν απολύτως για λαϊκό που αρχίζει.",
"k030dfcd7": "Ο ημερήσιος κύκλος των ακολουθιών &middot; όπου το επιτρέπει η ημέρα",
"k129ba7c3": "Οι σύντομες ακολουθίες μέσα στην ημέρα, από την Πρώτη Ώρα ως το Απόδειπνο. Οι τρεις καθημερινές προσευχές της Διδαχής είναι ο σπόρος αυτού του κύκλου· οι πλήρεις Ώρες δίνονται στο Ωρολόγιο.",
"k6ca85803": "Κανόνας κατά περίσταση &middot; πριν από τη μετάληψη των Μυστηρίων",
"kc26de5d2": "Το ταξίδι, η αρρώστια, η νυχτερινή εργασία, τα μικρά παιδιά, το πένθος και η εξάντληση διακόπτουν όλα έναν κανόνα. Δύο από τα παραπάνω κείμενα αφορούν άμεσα τούτο. Η Διδαχή δεν παρουσιάζει τον κανόνα της ως όλα ή τίποτε: όπου δεν μπορεί να βασταχθεί όλος ο ζυγός, «ό,τι μπορείς, τούτο κάνε». Και ο Κασσιανός επιτιμά όσους λογαριάζουν την προσευχή τους μόνο κατά τις ώρες που κλίνουν το γόνυ - πράγμα που βάζει την προσευχή εκτός εκείνων των ωρών μέσα στον λογαριασμό, όχι έξω από αυτόν.",
"k892d0484": "Η Ακολουθία της Θείας Μεταλήψεως είναι πραγματικό αγαθό και πραγματική κληρονομιά. Δεν είναι όμως εκείνο που καθιστά κάποιον ικανό να μεταλάβει. Ο άγιος Ιωάννης ο Χρυσόστομος πιάνει το ερώτημα του πόσο συχνά και πόσο πολύ, και αρνείται να το απαντήσει με τέτοιους όρους:",
"k74472bee": "Το κριτήριο που ονομάζει είναι η κατάσταση της συνειδήσεως, όχι ένας αριθμός. Ο άγιος Ιωάννης ο Κασσιανός αντιμετωπίζει το άλλο μισό υπό τίτλο κεφαλαίου που το λέει καθαρά: <em>ότι, μολονότι ομολογούμε πως δεν μπορούμε να είμαστε χωρίς αμαρτία, δεν οφείλουμε ωστόσο να απέχουμε από την Κοινωνία του Κυρίου.</em>",
"k89f08ec2": "Η αποχή από αίσθημα αναξιότητας, υποστηρίζει, είναι η ίδια η μεγαλύτερη τόλμη: όποιος απέχει ώσπου να γίνει άξιος, υποθέτει ότι κάποια άλλη ημέρα θα ήταν. Τα Μυστήρια δεν είναι αμοιβή για τους καθαρούς αλλά, κατά τα λόγια του, θα μας έκαναν αγίους και καθαρούς με το να τα λαμβάνουμε.",
"ke31bdf96": "Τούτο δεν είναι χαλάρωση του μέτρου. Είναι το ίδιο το μέτρο, και η Εκκλησία το βάζει στο στόμα καθενός που προσέρχεται:",
"kfbddc832": "Τα ίδια τα λόγια του Αποστόλου είναι <em>Χριστός Ιησούς ήλθεν εις τον κόσμον αμαρτωλούς σώσαι, ων πρώτος ειμι εγώ</em>, και η Εκκλησία δεν τα άφησε στην επιστολή: τα πήρε μέσα στην ακολουθία, και τα έδωσε σε κάθε κοινωνούντα να τα λέει σε πρώτο πρόσωπο, την ημέρα που μεταλαμβάνει. Άγιοι είναι εκείνοι που είπαν αυτή τη φράση και την εννοούσαν, όχι εκείνοι που έφτασαν σε σημείο όπου έπαψε να ισχύει.",
"k7981c058": "<strong>Εκείνο που ονομάζει η παράδοση</strong> είναι συνείδηση που δεν αναπαύεται σε αμετανόητη αμαρτία, ειρήνη με τον πλησίον, η ευχαριστιακή νηστεία, και υπακοή στον πνευματικό πατέρα ως προς την εξομολόγηση.",
"keeb5d497": "<strong>Η ευχαριστιακή νηστεία είναι κανονική, όχι εθιμική.</strong> Ο Αφρικανικός Κώδικας του 419 την απαιτούσε και επέτρεπε μία εξαίρεση τον χρόνο· η εν Τρούλλω Σύνοδος πήρε τον κανόνα εκείνο και αφαίρεσε την εξαίρεση:",
"k718a2fab": "Επειδή όμως τίποτε δεν μας οδηγεί να εγκαταλείψουμε την ακριβή τήρηση, ορίζουμε να ακολουθείται η αποστολική και πατερική παράδοση, και θεσπίζουμε ότι δεν είναι ορθό να λύεται η νηστεία την πέμπτη ημέρα της τελευταίας εβδομάδος της Τεσσαρακοστής, και έτσι να ατιμάζεται ολόκληρη η Τεσσαρακοστή.",
"k2426bb65": "Εκείνο που απαιτούν οι κανόνες είναι η νηστεία. Ο υπολογισμός της από τα προηγούμενα μεσάνυχτα είναι το έθιμο που τη φέρει. Όπου η Λειτουργία τελείται το εσπέρας - η Προηγιασμένη, και οι Λειτουργίες των Χριστουγέννων, των Θεοφανείων, της Μεγάλης Πέμπτης και του Μεγάλου Σαββάτου - το διάστημα ορίζεται από τον επίσκοπο και δεν μετριέται από τα μεσάνυχτα. Φάρμακα που πρέπει να ληφθούν, αρρώστια, εγκυμοσύνη, νηπιακή και βαθιά γεροντική ηλικία αντιμετωπίζονται από τον πνευματικό πατέρα. Το να ρωτήσει κανείς δεν είναι το ίδιο με το να απαλλαγεί, και ούτε το ένα ούτε το άλλο είναι λόγος να μένει μακριά από το Ποτήριο.",
"ka41be440": "Αρνείται να νομοθετήσει την έρημο - «δεν σας θέτω νόμο να καταλάβετε τα όρη και τις ερήμους, αλλά να είσθε αγαθοί και επιεικείς και σώφρονες, κατοικούντες μέσα στην πόλη» - και προσέχει να μη διαβαστεί ως υποτιμών τους μοναχούς, λέγοντας ότι μιλά «όχι κατηγορώντας εκείνους που ανέλαβαν τα όρη, αλλά θρηνώντας εκείνους που κατοικούν στις πόλεις, επειδή εξόρισαν από εκεί την αρετή». Ο μοναχός παραδίδει το ίδιο του το θέλημα σε γέροντα. Στον λαϊκό δίνεται το ίδιο πράγμα να παραδώσει, μέσα σε έναν γάμο, σε εργασία που δεν διάλεξε, στην υπομονή που κοστίζει ένα σπιτικό, και του ζητείται με τρόπο που κανένας κανόνας δεν μπορεί να τυπώσει εκ των προτέρων.",
"ke5795f78": "Νηστεία και εξομολόγηση",
"k6602f295": "Η προετοιμασία δεν είναι μόνο προσευχή. Η νηστεία της Τετάρτης και της Παρασκευής είναι το αρχαιότερο μέρος της, και βρίσκεται στο ίδιο κεφάλαιο της Διδαχής που δίνει τον κανόνα της προσευχής - το οποίο περιορίζει και τα δύο μισά με τον ίδιο τρόπο, προειδοποιώντας όχι κατά του να μη νηστεύει ή να μην προσεύχεται κανείς, αλλά κατά του να κάνει το ένα ή το άλλο <em>ως οι υποκριταί</em>.",
"k159fbd83": "Η εξομολόγηση πριν από τη μετάληψη αναμένεται σε ορισμένες παραδόσεις και σε άλλες όχι, και η διαφορά είναι παλαιά και όχι ζήτημα χαλαρότητας. Όποιος έμαθε να προετοιμάζεται στη μία παράδοση και βρεθεί έπειτα σε ενορία της άλλης, εύκολα μπορεί να εκλάβει διαφορά εθίμου ως κρίση εναντίον του.",
}
